use serde::{Deserialize,Serialize};use sha2::{Digest,Sha256};use std::collections::{BTreeMap,BTreeSet,VecDeque};
#[derive(Deserialize,Clone)]pub struct ExecutionNode{pub id:String,#[serde(default)]pub depends_on:Vec<String>,#[serde(default)]pub state:String,#[serde(default)]pub timeout_ms:u64,#[serde(default)]pub elapsed_ms:u64,#[serde(default)]pub attempt:u32,#[serde(default)]pub max_retries:u32,#[serde(default)]pub retry_backoff_ms:u64,#[serde(default)]pub idempotency_key:String,#[serde(default)]pub receipt_id:String,#[serde(default)]pub priority:i64}
#[derive(Deserialize)]pub struct ExecutionRequest{pub nodes:Vec<ExecutionNode>,#[serde(default)]pub receipts:Vec<String>,#[serde(default)]pub completed_idempotency_keys:Vec<String>,#[serde(default)]pub paused_node_id:Option<String>,#[serde(default)]pub resume_token:Option<String>}
#[derive(Serialize)]pub struct ExecutionIssue{pub code:&'static str,pub node_id:Option<String>,pub detail:String}
#[derive(Serialize)]pub struct RetryPlan{pub node_id:String,pub eligible:bool,pub next_attempt:u32,pub delay_ms:u64}
#[derive(Serialize)]pub struct ResumeContext{pub paused_node_id:Option<String>,pub resume_token:String,pub remaining_node_ids:Vec<String>}
#[derive(Serialize)]pub struct ExecutionPlanResult{pub order:Vec<String>,pub ready:Vec<String>,pub blocked:Vec<String>,pub timed_out:Vec<String>,pub skipped_idempotent:Vec<String>,pub retry_plan:Vec<RetryPlan>,pub issues:Vec<ExecutionIssue>,pub cycle_detected:bool,pub resume_context:ResumeContext,pub plan_sha256:String,pub engine:&'static str,pub owner_domain:&'static str,pub receipt_version:u32}
fn allowed_transition(from:&str,to:&str)->bool{matches!((from,to),("PENDING","READY")|("READY","RUNNING")|("RUNNING","SUCCEEDED")|("RUNNING","FAILED")|("RUNNING","PAUSED")|("PAUSED","READY")|("FAILED","READY"))||from==to}
fn plan_hash(order:&[String],issues:&[ExecutionIssue])->String{let value=serde_json::json!({"order":order,"issues":issues.iter().map(|i|(&i.code,&i.node_id,&i.detail)).collect::<Vec<_>>()});Sha256::digest(serde_json::to_vec(&value).unwrap_or_default()).iter().map(|b|format!("{b:02x}")).collect()}
pub fn plan_json(source:&str)->Result<String,String>{let r:ExecutionRequest=serde_json::from_str(source).map_err(|e|format!("EXECUTION_REQUEST_JSON:{e}"))?;if r.nodes.len()>100_000{return Err("EXECUTION_NODE_LIMIT".into())}let mut issues=Vec::new();let mut by_id=BTreeMap::new();for node in r.nodes{if node.id.trim().is_empty(){issues.push(ExecutionIssue{code:"NODE_ID_REQUIRED",node_id:None,detail:"empty id".into()});continue}if by_id.insert(node.id.clone(),node).is_some(){issues.push(ExecutionIssue{code:"NODE_ID_DUPLICATE",node_id:None,detail:"duplicate".into()});}}let receipts:BTreeSet<_>=r.receipts.into_iter().collect();let completed:BTreeSet<_>=r.completed_idempotency_keys.into_iter().collect();let mut indegree:BTreeMap<String,usize>=by_id.keys().map(|id|(id.clone(),0)).collect();let mut children:BTreeMap<String,Vec<String>>=BTreeMap::new();for(node_id,node)in &by_id{for dep in &node.depends_on{if !by_id.contains_key(dep){issues.push(ExecutionIssue{code:"DEPENDENCY_MISSING",node_id:Some(node_id.clone()),detail:dep.clone()});continue}*indegree.entry(node_id.clone()).or_default()+=1;children.entry(dep.clone()).or_default().push(node_id.clone());}if !node.receipt_id.is_empty()&&!receipts.contains(&node.receipt_id){issues.push(ExecutionIssue{code:"RECEIPT_MISSING",node_id:Some(node_id.clone()),detail:node.receipt_id.clone()});}if node.state.contains("->"){let parts:Vec<_>=node.state.split("->").collect();if parts.len()==2&&!allowed_transition(parts[0],parts[1]){issues.push(ExecutionIssue{code:"STATE_TRANSITION_INVALID",node_id:Some(node_id.clone()),detail:node.state.clone()});}}}let mut queue:Vec<_>=indegree.iter().filter(|(_,d)|**d==0).map(|(id,_)|id.clone()).collect();queue.sort_by(|a,b|by_id[b].priority.cmp(&by_id[a].priority).then_with(||a.cmp(b)));let mut deque:VecDeque<String>=queue.into();let mut order=Vec::new();while let Some(id)=deque.pop_front(){order.push(id.clone());if let Some(next)=children.get(&id){let mut unlocked=Vec::new();for child in next{if let Some(d)=indegree.get_mut(child){*d-=1;if *d==0{unlocked.push(child.clone())}}}unlocked.sort_by(|a,b|by_id[b].priority.cmp(&by_id[a].priority).then_with(||a.cmp(b)));for id in unlocked{deque.push_back(id)}}}let cycle=order.len()!=by_id.len();if cycle{issues.push(ExecutionIssue{code:"DAG_CYCLE_DETECTED",node_id:None,detail:"topological order incomplete".into()})}let mut ready=Vec::new();let mut blocked=Vec::new();let mut timed_out=Vec::new();let mut skipped=Vec::new();let mut retry_plan=Vec::new();for(id,node)in &by_id{if !node.idempotency_key.is_empty()&&completed.contains(&node.idempotency_key){skipped.push(id.clone());continue}if node.timeout_ms>0&&node.elapsed_ms>=node.timeout_ms{timed_out.push(id.clone());issues.push(ExecutionIssue{code:"NODE_TIMEOUT",node_id:Some(id.clone()),detail:format!("{}>={}",node.elapsed_ms,node.timeout_ms)});}let deps_ok=node.depends_on.iter().all(|dep|by_id.get(dep).map(|d|d.state=="SUCCEEDED"||d.state.ends_with("->SUCCEEDED")).unwrap_or(false));if deps_ok{ready.push(id.clone())}else{blocked.push(id.clone())}let eligible=node.attempt<node.max_retries;retry_plan.push(RetryPlan{node_id:id.clone(),eligible,next_attempt:node.attempt+1,delay_ms:node.retry_backoff_ms.saturating_mul(1u64<<node.attempt.min(20))});}ready.sort_by(|a,b|by_id[b].priority.cmp(&by_id[a].priority).then_with(||a.cmp(b)));let remaining=order.iter().filter(|id|!skipped.contains(id)).cloned().collect::<Vec<_>>();let token=r.resume_token.unwrap_or_else(||plan_hash(&remaining,&issues));let resume_context=ResumeContext{paused_node_id:r.paused_node_id,resume_token:token,remaining_node_ids:remaining};let plan_sha256=plan_hash(&order,&issues);let result=ExecutionPlanResult{order,ready,blocked,timed_out,skipped_idempotent:skipped,retry_plan,issues,cycle_detected:cycle,resume_context,plan_sha256,engine:"RUST",owner_domain:"execution",receipt_version:1};serde_json::to_string(&result).map_err(|e|format!("EXECUTION_RESULT_JSON:{e}"))}

#[cfg(test)]
mod tests { use super::*;
 #[test] fn detects_cycle(){let x=r#"{"nodes":[{"id":"A","depends_on":["B"]},{"id":"B","depends_on":["A"]}]}"#;let r=plan_json(x).unwrap();assert!(r.contains("DAG_CYCLE_DETECTED"));}
 #[test] fn order_is_deterministic(){let x=r#"{"nodes":[{"id":"B","priority":1},{"id":"A","priority":1}]}"#;assert_eq!(plan_json(x).unwrap(),plan_json(x).unwrap());}
}
